B: Ruined Square
以下のコードのような式で、残りの点の座標を求めることができます。
#include <stdio . h>
using namespace std ;
int main ()
{
int a , b ,
c , d ;
scanf (”%d%d%d%d” , &a , &b , &c , &d ) ;
int x = c −a , y = d −b ;
p r i n t f (”%d %d %d %d\n” , c −y , d + x ,
a −y , b + x ) ;
}

